function e(e,t){return"<style>.ppt-comments{break-before:page;padding:32px;box-sizing:border-box;font:16px/1.5 sans-serif}.ppt-comments li{break-inside:avoid;margin:20px 0}.ppt-comments p{white-space:pre-wrap;overflow-wrap:anywhere}</style>"+e.slides.map((e,i)=>{var n;return(n=e.comments)!=null&&n.length?`<section class="ppt-comments" data-slide="${i+1}"><h2>${i+1}</h2><ol>`+e.comments.map((e,i)=>`<li value="${t(String(e.idx??i+1))}"><b>${t(e.author)}</b>`+(e.date?`<time> · ${t(e.date)}</time>`:"")+`<p>${t(e.text)}</p></li>`).join("")+"</ol></section>":""}).join("")}function t(t,i,n,a){return`<!doctype html><html><head><meta charset="utf-8"><title>slides</title><style>@page{size:${Math.round(t.width)}px ${Math.round(t.height)}px;margin:0}html,body{margin:0;padding:0}.pg{page-break-after:always;width:100vw;height:100vh;display:flex;align-items:center;justify-content:center}.pg svg{width:100%;height:100%}</style></head><body>`+i.map(e=>`<div class="pg">${e}</div>`).join("")+(n?e(t,a):"")+"</body></html>"}export{e as printCommentAppendix,t as printDocument};